import sys

def min_bridge_downtime(N, arrival_times):
    # Initialize the DP table
    dp = [[float('inf')] * 2 for _ in range(N + 1)]
    dp[0][0] = 0  # No boats, bridge is down initially

    for i in range(1, N + 1):
        T_i = arrival_times[i - 1]

        # Case 1: Bridge is down before the current boat arrives
        if T_i - dp[i - 1][0] >= 60:
            dp[i][0] = dp[i - 1][0] + 60

        # Case 2: Bridge is up before the current boat arrives
        if T_i - dp[i - 1][1] >= 60:
            dp[i][1] = dp[i - 1][1] + 60

        # Case 3: Bridge is down when the current boat arrives
        if T_i - dp[i - 1][0] >= 60:
            dp[i][0] = min(dp[i][0], dp[i - 1][0] + 60)

        # Case 4: Bridge is up when the current boat arrives
        if T_i - dp[i - 1][1] >= 60:
            dp[i][1] = min(dp[i][1], dp[i - 1][1] + 60)

        # Case 5: Bridge is up after the current boat passes
        if T_i - dp[i - 1][1] >= 60:
            dp[i][1] = min(dp[i][1], dp[i - 1][1] + 60 + 20)

        # Case 6: Bridge is down after the current boat passes
        if T_i - dp[i - 1][0] >= 60:
            dp[i][0] = min(dp[i][0], dp[i - 1][0] + 60 + 20)

    return min(dp[N][0], dp[N][1])

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    arrival_times = list(map(int, data[1:]))

    result = min_bridge_downtime(N, arrival_times)
    print(result)

if __name__ == "__main__":
    main()
